import {FrameRenderer} from './render.js';
export function crc32(bytes){let crc=-1;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
export function zipFiles(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;const header=(size,signature)=>{const bytes=new Uint8Array(size),view=new DataView(bytes.buffer);view.setUint32(0,signature,true);return {bytes,view};};for(const file of files){const name=encoder.encode(file.name),data=file.bytes,crc=crc32(data),local=header(30,0x04034b50);local.view.setUint16(4,20,true);local.view.setUint16(6,0x800,true);local.view.setUint16(12,0x21,true);local.view.setUint32(14,crc,true);local.view.setUint32(18,data.length,true);local.view.setUint32(22,data.length,true);local.view.setUint16(26,name.length,true);parts.push(local.bytes,name,data);const c=header(46,0x02014b50);c.view.setUint16(4,20,true);c.view.setUint16(6,20,true);c.view.setUint16(8,0x800,true);c.view.setUint16(14,0x21,true);c.view.setUint32(16,crc,true);c.view.setUint32(20,data.length,true);c.view.setUint32(24,data.length,true);c.view.setUint16(28,name.length,true);c.view.setUint32(42,offset,true);central.push(c.bytes,name);offset+=30+name.length+data.length;}const centralSize=central.reduce((n,p)=>n+p.length,0),end=header(22,0x06054b50);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,centralSize,true);end.view.setUint32(16,offset,true);return new Blob([...parts,...central,end.bytes],{type:'application/zip'});}
export async function pngFrames(p,w,h,signal,progress){const renderer=new FrameRenderer(p,w,h,true),files=[],total=Math.ceil(p.duration*p.fps);let bytes=0;for(let i=0;i<total;i++){if(signal.aborted)throw new DOMException('Render cancelled','AbortError');const canvas=await renderer.frame(i/p.fps),blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('PNG encoding failed.')),'image/png'));const data=new Uint8Array(await blob.arrayBuffer());bytes+=data.length;if(bytes>512*1024*1024)throw Error('PNG sequence exceeds 512 MB. Shorten the composition or reduce its resolution.');files.push({name:`frame-${String(i+1).padStart(5,'0')}.png`,bytes:data});progress(i+1,total);if(i%8===0)await new Promise(resolve=>setTimeout(resolve,0));}files.push({name:'sequence.json',bytes:new TextEncoder().encode(JSON.stringify({width:w,height:h,fps:p.fps,frames:total,duration:total/p.fps,transparent:true},null,2))});return {blob:zipFiles(files),preview:new Blob([files[0].bytes],{type:'image/png'})};}
